CREATE   PROCEDURE [synapse_ce].[usp_Insert_territory]
AS
BEGIN
	INSERT INTO [synapse_ce].[territory]
	(
		[apitil_slaid],
		[apitil_slaid_entitytype],
		[apitil_slaidname],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[description],
		[entityimage_timestamp],
		[entityimage_url],
		[entityimageid],
		[exchangerate],
		[Id],
		[importsequencenumber],
		[managerid],
		[managerid_entitytype],
		[manageridname],
		[manageridyominame],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[name],
		[organizationid],
		[organizationid_entitytype],
		[organizationidname],
		[overriddencreatedon],
		[parentterritoryid],
		[parentterritoryid_entitytype],
		[parentterritoryidname],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[territoryid],
		[timezoneruleversionnumber],
		[transactioncurrencyid],
		[transactioncurrencyid_entitytype],
		[transactioncurrencyidname],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[apitil_slaid],
		stg.[apitil_slaid_entitytype],
		stg.[apitil_slaidname],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[description],
		stg.[entityimage_timestamp],
		stg.[entityimage_url],
		stg.[entityimageid],
		stg.[exchangerate],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[managerid],
		stg.[managerid_entitytype],
		stg.[manageridname],
		stg.[manageridyominame],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[name],
		stg.[organizationid],
		stg.[organizationid_entitytype],
		stg.[organizationidname],
		stg.[overriddencreatedon],
		stg.[parentterritoryid],
		stg.[parentterritoryid_entitytype],
		stg.[parentterritoryidname],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[territoryid],
		stg.[timezoneruleversionnumber],
		stg.[transactioncurrencyid],
		stg.[transactioncurrencyid_entitytype],
		stg.[transactioncurrencyidname],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[territory] stg
		LEFT JOIN [synapse_ce].[territory] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
